package org.sleepwell.app;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

/** Independent private database: rules/credentials never enter sleep-record exports. */
final class AutomationStore extends SQLiteOpenHelper {
    interface Vault {String seal(String text)throws Exception;String open(String text)throws Exception;}
    private final Vault vault;
    static final class Row {final String id,name,event,transport,status;final long revision;final boolean enabled;Row(Cursor c){id=c.getString(0);name=c.getString(1);event=c.getString(2);transport=c.getString(3);enabled=c.getInt(4)!=0;revision=c.getLong(5);status=c.getString(6);}}
    static final class Pending {final long row,revision,created;final String rule;final int attempts;final AutomationEvent event;Pending(Cursor c){row=c.getLong(0);rule=c.getString(1);revision=c.getLong(2);created=c.getLong(3);attempts=c.getInt(4);event=new AutomationEvent(c.getString(5),AutomationEvent.Kind.valueOf(c.getString(6)),c.getLong(7),c.getInt(8)!=0,c.getString(9));}}
    AutomationStore(Context context){this(context,"automations-v1.db",new AutomationSecrets());}
    AutomationStore(Context context,String name,Vault vault){super(context,name,null,2);this.vault=vault;}
    @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,event TEXT NOT NULL,transport TEXT NOT NULL,enabled INTEGER NOT NULL,revision INTEGER NOT NULL,config TEXT NOT NULL,status TEXT NOT NULL DEFAULT '')");db.execSQL("CREATE TABLE deliveries(id INTEGER PRIMARY KEY AUTOINCREMENT,rule TEXT NOT NULL,revision INTEGER NOT NULL,created INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,event_id TEXT NOT NULL,event TEXT NOT NULL,event_time INTEGER NOT NULL,test INTEGER NOT NULL,sound_class TEXT NOT NULL DEFAULT '',due INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',UNIQUE(rule,revision,event_id))");db.execSQL("CREATE INDEX delivery_due ON deliveries(state,due)");}
    @Override public void onUpgrade(SQLiteDatabase db,int old,int next){if(old<2)db.execSQL("ALTER TABLE deliveries ADD COLUMN sound_class TEXT NOT NULL DEFAULT ''");if(next>2)throw new IllegalStateException("Unsupported automation database");}
    List<Row> rows(){List<Row> rows=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,event,transport,enabled,revision,status FROM rules ORDER BY rowid",null)){while(c.moveToNext())rows.add(new Row(c));}return rows;}
    AutomationRule rule(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,event,transport,enabled,revision,config FROM rules WHERE id=?",new String[]{id})){if(!c.moveToFirst())return null;JSONObject config=new JSONObject(vault.open(c.getString(6)));AutomationRule rule=new AutomationRule(c.getString(0),c.getString(1),AutomationEvent.Kind.valueOf(c.getString(2)),AutomationRule.Transport.valueOf(c.getString(3)),c.getInt(4)!=0,c.getLong(5),config.getString("destination"),config.getString("topic"),config.getString("username"),config.getString("secret"));rule.validate();return rule;}}
    AutomationRule save(AutomationRule draft)throws Exception{draft.validate();String sealed=vault.seal(new JSONObject().put("destination",draft.destination).put("topic",draft.topic).put("username",draft.username).put("secret",draft.secret).toString());SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{long revision=0;try(Cursor c=db.rawQuery("SELECT revision FROM rules WHERE id=?",new String[]{draft.id})){if(c.moveToFirst())revision=c.getLong(0);else try(Cursor count=db.rawQuery("SELECT COUNT(*) FROM rules",null)){count.moveToFirst();if(count.getInt(0)>=20)throw new IllegalArgumentException("Keep at most 20 rules.");}}if(revision!=draft.revision)throw new IllegalStateException("Rule changed. Reopen it before saving.");revision++;ContentValues v=new ContentValues();v.put("id",draft.id);v.put("name",draft.name.trim());v.put("event",draft.event.name());v.put("transport",draft.transport.name());v.put("enabled",draft.enabled?1:0);v.put("revision",revision);v.put("config",sealed);v.put("status",draft.enabled?"Ready for new events":"Off");db.insertWithOnConflict("rules",null,v,SQLiteDatabase.CONFLICT_REPLACE);db.delete("deliveries","rule=? AND state='pending'",new String[]{draft.id});db.setTransactionSuccessful();return draft.revision(revision);}finally{db.endTransaction();}}
    void enabled(String id,long revision,boolean enabled){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("enabled",enabled?1:0);v.put("revision",revision+1);v.put("status",enabled?"Ready for new events":"Off");if(db.update("rules",v,"id=? AND revision=?",new String[]{id,""+revision})!=1)throw new IllegalStateException("Rule changed. Refresh the list.");db.delete("deliveries","rule=? AND state='pending'",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    void delete(String id){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.delete("deliveries","rule=?",new String[]{id});db.delete("rules","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    int enqueue(AutomationEvent event,String onlyRule){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();int inserted=0;try{db.delete("deliveries","state!='pending' AND id NOT IN (SELECT id FROM deliveries WHERE state!='pending' ORDER BY id DESC LIMIT 100)",null);for(Row rule:rows()){if(!rule.enabled||!rule.event.equals(event.kind.name())||onlyRule!=null&&!rule.id.equals(onlyRule))continue;int count;try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM deliveries WHERE state='pending'",null)){c.moveToFirst();count=c.getInt(0);}if(count>=100){status(rule.id,rule.revision,"Queue full; event not queued");continue;}ContentValues v=new ContentValues();v.put("rule",rule.id);v.put("revision",rule.revision);v.put("created",event.time);v.put("event_id",event.id);v.put("event",event.kind.name());v.put("event_time",event.time);v.put("test",event.test?1:0);v.put("sound_class",event.soundClass);v.put("due",event.time);if(db.insertWithOnConflict("deliveries",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1){inserted++;status(rule.id,rule.revision,"Queued");}}db.setTransactionSuccessful();return inserted;}finally{db.endTransaction();}}
    Pending next(long now){try(Cursor c=getReadableDatabase().rawQuery("SELECT id,rule,revision,created,attempts,event_id,event,event_time,test,sound_class FROM deliveries WHERE state='pending' AND due<=? ORDER BY due,id LIMIT 1",new String[]{""+now})){return c.moveToFirst()?new Pending(c):null;}}
    long due(){try(Cursor c=getReadableDatabase().rawQuery("SELECT MIN(due) FROM deliveries WHERE state='pending'",null)){return c.moveToFirst()&&!c.isNull(0)?c.getLong(0):-1;}}
    boolean current(Pending pending){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM rules WHERE id=? AND revision=? AND enabled=1",new String[]{pending.rule,""+pending.revision})){return c.moveToFirst();}}
    void result(Pending p,String message,boolean retry,long now){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{int attempts=p.attempts+1;boolean again=AutomationDelivery.retry(retry,attempts,p.created,now);ContentValues v=new ContentValues();v.put("attempts",attempts);v.put("state",again?"pending":"done");v.put("due",again?now+AutomationDelivery.retryDelay(attempts):now);db.update("deliveries",v,"id=? AND revision=?",new String[]{""+p.row,""+p.revision});status(p.rule,p.revision,again?message+" · retry "+attempts+"/"+AutomationDelivery.MAX_ATTEMPTS:message);db.setTransactionSuccessful();}finally{db.endTransaction();}}
    private void status(String id,long revision,String message){ContentValues v=new ContentValues();v.put("status",message);getWritableDatabase().update("rules",v,"id=? AND revision=?",new String[]{id,""+revision});}
}
